class Solution { static final int MOD=1_000_000_007;public int colorTheGrid(int m,int n){List<Integer> states=new ArrayList<>();int limit=1;for(int i=0;i<m;i++)limit*=3;for(int state=0;state<limit;state++){int value=state,previous=-1;boolean valid=true;for(int row=0;row<m;row++){int color=value%3;value/=3;if(color==previous)valid=false;previous=color;}if(valid)states.add(state);}int size=states.size();boolean[][] compatible=new boolean[size][size];for(int i=0;i<size;i++)for(int j=0;j<size;j++){int a=states.get(i),b=states.get(j);compatible[i][j]=true;for(int row=0;row<m;row++){if(a%3==b%3)compatible[i][j]=false;a/=3;b/=3;}}long[] dp=new long[size];Arrays.fill(dp,1);for(int col=1;col<n;col++){long[] next=new long[size];for(int current=0;current<size;current++)for(int previous=0;previous<size;previous++)if(compatible[previous][current])next[current]=(next[current]+dp[previous])%MOD;dp=next;}long answer=0;for(long ways:dp)answer=(answer+ways)%MOD;return (int)answer;} }
